from cwecrawler.items import CwecrawlerItem
import scrapy
import re

with open('websites.txt', 'r') as f:
    cwe_capec_label = f.readlines()

urls = [url.strip() for url in cwe_capec_label]

class CweSpider(scrapy.Spider):
    name = 'cwe_spider'
    start_urls = urls

    def parse(self, response):
        cwe_item = CwecrawlerItem()
        title_text = response.xpath('//title/text()').get()
        cwe_id_match = re.search(r'CWE-\d+', title_text)
        if cwe_id_match:
            cwe_item['cwe_id'] = cwe_id_match.group()
        else:
            cwe_item['cwe_id'] = None
        cwe_item['cwe_canfollow'] = response.xpath("//tr[td[contains(., 'CanFollow')]]/td[3]/text()").getall()
        
        yield cwe_item

